def _cov_query(h, fn, p, cap):
    buf = (ctypes.c_double * cap)()
    n = fn(h, p, buf, cap)
    if n < 0:
        raise AraelError(n, _err(h))
    return buf


def _shape_1(buf):
    return float(buf[0])


def _shape_2(buf):
    return _m.matrix2d.from_elements(buf[0], buf[1], buf[2], buf[3])


def _shape_3(buf):
    return _m.matrix3d.from_elements(*[buf[i] for i in range(9)])


def _shape_n(buf, n):
    return tuple(tuple(buf[r * n + c] for c in range(n)) for r in range(n))


class Covariance:
    """Covariance prepared at the solution; per-entity queries
    (marginal/conditional by param count: 1 -> float, 2/3 ->
    matrix2d/3d, larger -> row-major tuples). Valid until the model is
    dropped or reassembled."""

    __slots__ = ("_h",)

    def __init__(self, h):
        self._h = h

    def marginal(self, e):
        """The entity's marginal covariance block."""
        if isinstance(e, PointLandmark):
            return (_shape_3)(_cov_query(self._h, _f.path_point_landmark_marginal_cov, e._p, 9))
        if isinstance(e, Pose):
            return (lambda b: _shape_n(b, 6))(_cov_query(self._h, _f.path_pose_marginal_cov, e._p, 36))
        raise TypeError("no marginal for %r" % (e,))

    def conditional(self, e):
        """Conditional covariance (all other parameters fixed)."""
        if isinstance(e, PointLandmark):
            return (_shape_3)(_cov_query(self._h, _f.path_point_landmark_conditional_cov, e._p, 9))
        if isinstance(e, Pose):
            return (lambda b: _shape_n(b, 6))(_cov_query(self._h, _f.path_pose_conditional_cov, e._p, 36))
        raise TypeError("no conditional for %r" % (e,))

    def std_dev(self, e):
        """Per-parameter standard deviations (every CovMode, incl.
        TriDiagonal)."""
        if isinstance(e, PointLandmark):
            return list(_cov_query(self._h, _f.path_point_landmark_std_dev, e._p, 3))
        if isinstance(e, Pose):
            return list(_cov_query(self._h, _f.path_pose_std_dev, e._p, 6))
        raise TypeError("no std_dev for %r" % (e,))
    def _cross_point_landmark_point_landmark(self, a, b):
        buf = (ctypes.c_double * 9)()
        rows = _f.path_point_landmark_point_landmark_cross_cov(self._h, a._p, b._p, buf, 9)
        if rows < 0:
            raise AraelError(rows, _err(self._h))
        return tuple(tuple(buf[r * 3 + c] for c in range(3))
                     for r in range(rows))
    def _cross_point_landmark_pose(self, a, b):
        buf = (ctypes.c_double * 18)()
        rows = _f.path_point_landmark_pose_cross_cov(self._h, a._p, b._p, buf, 18)
        if rows < 0:
            raise AraelError(rows, _err(self._h))
        return tuple(tuple(buf[r * 6 + c] for c in range(6))
                     for r in range(rows))
    def _cross_pose_point_landmark(self, a, b):
        buf = (ctypes.c_double * 18)()
        rows = _f.path_pose_point_landmark_cross_cov(self._h, a._p, b._p, buf, 18)
        if rows < 0:
            raise AraelError(rows, _err(self._h))
        return tuple(tuple(buf[r * 3 + c] for c in range(3))
                     for r in range(rows))
    def _cross_pose_pose(self, a, b):
        buf = (ctypes.c_double * 36)()
        rows = _f.path_pose_pose_cross_cov(self._h, a._p, b._p, buf, 36)
        if rows < 0:
            raise AraelError(rows, _err(self._h))
        return tuple(tuple(buf[r * 6 + c] for c in range(6))
                     for r in range(rows))

    def cross(self, a, b):
        """Row-major cross-covariance block between two entities."""
        if isinstance(a, PointLandmark) and isinstance(b, PointLandmark):
            return self._cross_point_landmark_point_landmark(a, b)
        if isinstance(a, PointLandmark) and isinstance(b, Pose):
            return self._cross_point_landmark_pose(a, b)
        if isinstance(a, Pose) and isinstance(b, PointLandmark):
            return self._cross_pose_point_landmark(a, b)
        if isinstance(a, Pose) and isinstance(b, Pose):
            return self._cross_pose_pose(a, b)
        raise TypeError("no cross-covariance for %r x %r" % (a, b))


class PathPosesDeque:
    """View of `poses` (deque of Pose); wrappers stay valid per the
    C++ contract, mutating while iterating is undefined."""

    __slots__ = ("_p",)

    def __init__(self, p):
        self._p = p

    def __len__(self):
        return _f.path_poses_len(self._p)

    def reserve(self, additional):
        _f.path_poses_reserve(self._p, additional)

    def __getitem__(self, i):
        if isinstance(i, PoseRef):
            return Pose(_f.path_poses_get(self._p, i.raw))
        n = len(self)
        if i < 0:
            i += n
        if not 0 <= i < n:
            raise IndexError(i)
        return Pose(_f.path_poses_at(self._p, i))

    def __iter__(self):
        for i in range(len(self)):
            yield Pose(_f.path_poses_at(self._p, i))

    def clear(self):
        _f.path_poses_clear(self._p)

    def truncate(self, n):
        _f.path_poses_truncate(self._p, n)

    def push_back(self):
        return Pose(_f.path_poses_push_back(self._p))

    def push_front(self):
        return Pose(_f.path_poses_push_front(self._p))

    def pop_back(self):
        """Drops one end; False when already empty."""
        return _f.path_poses_pop_back(self._p)

    def pop_front(self):
        """Drops one end; False when already empty."""
        return _f.path_poses_pop_front(self._p)

    def get(self, r):
        return Pose(_f.path_poses_get(self._p, _raw(r)))

    def __contains__(self, r):
        return _f.path_poses_contains(self._p, _raw(r))

    def try_get(self, r):
        """The element, or None for a stale or foreign ref."""
        p = _f.path_poses_try_get(self._p, _raw(r))
        return Pose(p) if p else None

    def ref_at(self, i):
        return PoseRef(_f.path_poses_ref_at(self._p, i))

    def front_ref(self):
        """Ref of the first element; null when empty."""
        return PoseRef(_f.path_poses_front_ref(self._p))

    def back_ref(self):
        """Ref of the last element; null when empty."""
        return PoseRef(_f.path_poses_back_ref(self._p))


class PathLandmarksArena:
    """View of `landmarks` (arena of PointLandmark); wrappers stay valid per the
    C++ contract, mutating while iterating is undefined."""

    __slots__ = ("_p",)

    def __init__(self, p):
        self._p = p

    def __len__(self):
        return _f.path_landmarks_len(self._p)

    def reserve(self, additional):
        _f.path_landmarks_reserve(self._p, additional)

    def push(self):
        """New element's ref (get()/[] take it back)."""
        return PointLandmarkRef(_f.path_landmarks_push(self._p))

    def remove(self, r):
        return _f.path_landmarks_remove(self._p, _raw(r))

    def clear(self):
        _f.path_landmarks_clear(self._p)

    def __getitem__(self, r):
        return PointLandmark(_f.path_landmarks_get(self._p, _raw(r)))

    def __iter__(self):
        """Live slots in order; yields element wrappers (refs() for
        the refs)."""
        r = _f.path_landmarks_first(self._p)
        while r != 0xFFFFFFFF:
            yield PointLandmark(_f.path_landmarks_get(self._p, r))
            r = _f.path_landmarks_next(self._p, r)

    def refs(self):
        r = _f.path_landmarks_first(self._p)
        while r != 0xFFFFFFFF:
            yield PointLandmarkRef(r)
            r = _f.path_landmarks_next(self._p, r)

    def get(self, r):
        return PointLandmark(_f.path_landmarks_get(self._p, _raw(r)))

    def __contains__(self, r):
        return _f.path_landmarks_contains(self._p, _raw(r))

    def try_get(self, r):
        """The element, or None for a stale or foreign ref."""
        p = _f.path_landmarks_try_get(self._p, _raw(r))
        return PointLandmark(p) if p else None


