class Path:
    """The model. Owns the underlying Rust instance; free() (or GC)
    releases it. One model, one thread."""

    def __init__(self):
        load()
        self._p = _f.path_new()

    def free(self):
        if self._p:
            _f.path_free(self._p)
            self._p = None

    def __del__(self):
        try:
            self.free()
        except Exception:
            pass

    def _solved(self, code, res):
        if code < 0:
            raise AraelError(code, _err(self._p))
        return res

    def solve_dense(self, cfg=None):
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.path_solve_dense(self._p, ctypes.byref(cfg),
                                     ctypes.byref(r)), r)

    def solve_sparse(self, cfg=None):
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.path_solve_sparse(self._p, ctypes.byref(cfg),
                                      ctypes.byref(r)), r)

    def solve_band(self, kd, cfg=None):
        """Band Cholesky solve; kd is the half-bandwidth in scalar
        parameters."""
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.path_solve_band(self._p, kd, ctypes.byref(cfg),
                                    ctypes.byref(r)), r)

    def assemble_covariance(self, mode=CovMode.ALL_MARGINALS):
        code = _f.path_assemble_covariance(self._p, int(mode))
        if code != 0:
            raise AraelError(code, _err(self._p))
        return Covariance(self._p)

    def cost(self):
        """Total cost at the current parameter values (no solve)."""
        return _f.path_cost(self._p)

    def validate(self):
        """Empty string when the model is clean, the diagnostic text
        otherwise."""
        return _f.path_validate(self._p).decode()

    def last_error(self):
        return _err(self._p)

    def last_report(self):
        """Text report of the last completed solve; '' before one."""
        return _f.path_last_report(self._p, False).decode()

    def last_pretty_report(self):
        """last_report() with colour and box-drawing glyphs."""
        return _f.path_last_report(self._p, True).decode()

    @property
    def poses(self):
        return PathPosesDeque(self._p)

    @property
    def landmarks(self):
        return PathLandmarksArena(self._p)

    @property
    def pose_pairs(self):
        return PathPosePairsVec(self._p)

    @property
    def drift_rho_isigma(self):
        return _f.path_drift_rho_isigma(self._p)

    @drift_rho_isigma.setter
    def drift_rho_isigma(self, v):
        _f.path_set_drift_rho_isigma(self._p, v)

    @property
    def tilt_isigma(self):
        return _f.path_tilt_isigma(self._p)

    @tilt_isigma.setter
    def tilt_isigma(self, v):
        _f.path_set_tilt_isigma(self._p, v)

    @property
    def frine_isigma_scale(self):
        return _f.path_frine_isigma_scale(self._p)

    @frine_isigma_scale.setter
    def frine_isigma_scale(self, v):
        _f.path_set_frine_isigma_scale(self._p, v)

    @property
    def frine_c2(self):
        return _f.path_frine_c2(self._p)

    @frine_c2.setter
    def frine_c2(self, v):
        _f.path_set_frine_c2(self._p, v)

    @property
    def frine_cauchy(self):
        return _f.path_frine_cauchy(self._p)

    @frine_cauchy.setter
    def frine_cauchy(self, v):
        _f.path_set_frine_cauchy(self._p, v)

    @property
    def gps_c2(self):
        return _f.path_gps_c2(self._p)

    @gps_c2.setter
    def gps_c2(self, v):
        _f.path_set_gps_c2(self._p, v)

